package com.johnny.hotel.group;import com.johnny.hotel.common.Result;import com.johnny.hotel.pagination.PageResult;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController@RequiredArgsConstructor@RequestMapping("/api/admin/groups")@PreAuthorize("hasAnyRole('STAFF','FINANCE','MANAGER','OWNER','SUPER_ADMIN')")public class GroupReservationController{private final GroupReservationService s;@GetMapping public Result<PageResult<GroupModels.Group>> page(@RequestParam(required=false)Integer status,@RequestParam(required=false)String q,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize){return Result.success(s.page(status,q,page,pageSize));}@GetMapping("/{id}")public Result<GroupModels.Group> get(@PathVariable Long id){return Result.success(s.get(id));}@GetMapping("/{id}/blocks")public Result<List<GroupModels.Block>> blocks(@PathVariable Long id){return Result.success(s.blocks(id));}@GetMapping("/{id}/rooming")public Result<PageResult<GroupModels.Entry>> entries(@PathVariable Long id,@RequestParam(required=false)Integer status,@RequestParam(required=false)Long blockId,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize){return Result.success(s.entries(id,status,blockId,page,pageSize));}@GetMapping("/{id}/bookings")public Result<PageResult<com.johnny.hotel.entity.Booking>> children(@PathVariable Long id,@RequestParam(required=false)Integer status,@RequestParam(required=false)Integer page,@RequestParam(required=false)Integer pageSize){return Result.success(s.children(id,status,page,pageSize));}@PostMapping@PreAuthorize("hasAnyRole('MANAGER','OWNER','SUPER_ADMIN')")public Result<GroupModels.Group> create(@Valid@RequestBody GroupRequests.Create r){return Result.success(s.create(r));}@PostMapping("/{id}/blocks")@PreAuthorize("hasAnyRole('MANAGER','OWNER','SUPER_ADMIN')")public Result<GroupModels.Block> block(@PathVariable Long id,@Valid@RequestBody GroupRequests.Block r){return Result.success(s.addBlock(id,r));}@PostMapping("/{id}/confirm")@PreAuthorize("hasAnyRole('MANAGER','OWNER','SUPER_ADMIN')")public Result<GroupModels.Group> confirm(@PathVariable Long id){return Result.success(s.confirm(id));}@PostMapping("/{id}/cancel")@PreAuthorize("hasAnyRole('MANAGER','OWNER','SUPER_ADMIN')")public Result<GroupModels.Group> cancel(@PathVariable Long id){return Result.success(s.cancel(id));}@PostMapping("/blocks/{id}/release")@PreAuthorize("hasAnyRole('MANAGER','OWNER','SUPER_ADMIN')")public Result<GroupModels.Block> release(@PathVariable Long id,@Valid@RequestBody GroupRequests.Quantity r){return Result.success(s.release(id,r.getQuantity()));}@PostMapping("/blocks/{id}/cutoff")@PreAuthorize("hasAnyRole('MANAGER','OWNER','SUPER_ADMIN')")public Result<GroupModels.Block> cutoff(@PathVariable Long id){return Result.success(s.cutoff(id));}@PostMapping("/{id}/rooming")@PreAuthorize("hasAnyRole('STAFF','MANAGER','OWNER','SUPER_ADMIN')")public Result<GroupModels.Entry> entry(@PathVariable Long id,@Valid@RequestBody GroupRequests.Entry r){return Result.success(s.addEntry(id,r));}@PutMapping("/rooming/{id}/guest")@PreAuthorize("hasAnyRole('STAFF','MANAGER','OWNER','SUPER_ADMIN')")public Result<GroupModels.Entry> guest(@PathVariable Long id,@RequestBody GroupRequests.Guest r){return Result.success(s.attach(id,r.getGuestProfileId()));}@PostMapping("/rooming/{id}/pickup")@PreAuthorize("hasAnyRole('STAFF','MANAGER','OWNER','SUPER_ADMIN')")public Result<GroupModels.Entry> pickup(@PathVariable Long id){return Result.success(s.pickup(id));}}

